@using sv_04e1dc84ca2e45b696e903c792e2045b.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<select class="form-select form-select-sm"
        value="@WarehouseState.CurrentWarehouseId"
        @onchange="OnWarehouseChanged"
        style="max-width: 220px;">
    @foreach (var wh in WarehouseState.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleWarehouseChanged;
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
            // Re-fetch alerts for the newly selected warehouse
            AlertService.CurrentLowStockCount =
                await AlertService.GetLowStockCountAsync(newId);
            AlertService.RaiseAlertDataChanged();
        }
    }

    private void HandleWarehouseChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleWarehouseChanged;
    }
}

@using sv_04e1dc84ca2e45b696e903c792e2045b.Services
@inject InventoryAlertService AlertService
@implements IDisposable

<span class="badge bg-danger rounded-pill">@AlertService.CurrentLowStockCount</span>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertDataChanged += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
            AlertService.OnAlertDataChanged -= _handler;
    }
}

