@page "/dashboard"
@rendermode InteractiveServer
@using sv_04e1dc84ca2e45b696e903c792e2045b.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-5">
                    @WarehouseState.AvailableWarehouses
                        .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card border-danger">
            <div class="card-body text-center">
                <h5 class="card-title text-danger">Low Stock Alerts</h5>
                <p class="display-4 text-danger">@AlertService.CurrentLowStockCount</p>
                <small class="text-muted">Items below minimum level</small>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Polling Status</h5>
                <p class="card-text">
                    <span class="badge bg-success">Active</span>
                    <br />
                    <small class="text-muted">Refreshing every 10 seconds</small>
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        _alertHandler = () => InvokeAsync(StateHasChanged);

        WarehouseState.OnChange += _warehouseHandler;
        AlertService.OnAlertDataChanged += _alertHandler;

        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.StopPolling();

        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
        if (_alertHandler is not null)
            AlertService.OnAlertDataChanged -= _alertHandler;
    }
}

